using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
public class LoadTypesProbe {
 public static int Main(string[] args){string target=args[0],editor=args[1],output=args[2];var dirs=new[]{Path.Combine(target,"Assets/OriginalRecovered/Plugins"),Path.Combine(target,"Library/ScriptAssemblies"),Path.Combine(editor,"Data/Managed/UnityEngine"),Path.Combine(editor,"Data/Managed"),Path.Combine(editor,"Data/MonoBleedingEdge/lib/mono/4.5")};var resolutions=new List<object>();AppDomain.CurrentDomain.AssemblyResolve+=(o,e)=>{string n=new AssemblyName(e.Name).Name;if(n=="System.Core")return typeof(Enumerable).Assembly;foreach(var dir in dirs){var p=Path.Combine(dir,n+".dll");if(File.Exists(p)){resolutions.Add(new{requested=e.Name,path=p});return Assembly.LoadFrom(p);}}resolutions.Add(new{requested=e.Name,path="UNRESOLVED"});return null;};var a=Assembly.LoadFrom(Path.Combine(dirs[0],"OutGame.dll"));var errors=new List<string>();int loaded=0,total=0;try{var ts=a.GetTypes();total=loaded=ts.Length;}catch(ReflectionTypeLoadException ex){total=ex.Types.Length;loaded=ex.Types.Count(x=>x!=null);errors.AddRange(ex.LoaderExceptions.Select(x=>x.ToString()));}var perType=new List<object>();foreach(var line in File.ReadAllLines(Path.Combine(output,"type-tokens.txt"))){var parts=line.TrimStart('\uFEFF').Split('|');if(parts.Length!=2)continue;try{var t=a.ManifestModule.ResolveType(Convert.ToInt32(parts[0]));var fields=t.GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly);foreach(var f in fields){var ft=f.FieldType.FullName;}var bases=t.BaseType==null?null:t.BaseType.FullName;}catch(Exception ex){perType.Add(new{token=parts[0],type=parts[1],error=ex.ToString()});}}var j=new JavaScriptSerializer(){MaxJsonLength=int.MaxValue};File.WriteAllText(Path.Combine(output,"mono-probe.json"),j.Serialize(new{assembly=a.FullName,path=a.Location,total=total,loaded=loaded,getTypesErrors=errors,individualTypeErrors=perType,resolutions=resolutions,scope="Unity2023 standalone Mono; not Unity editor domain"}));Console.WriteLine("GetTypes loaded "+loaded+"/"+total+"; loader errors "+errors.Count+"; individual type failures "+perType.Count);foreach(var e in errors.Distinct())Console.WriteLine(e);return 0;}
}
